import numpy as np
def _vel(X, T, M, b, c, tv):
    X = np.asarray(X, dtype=float); n = len(X)
    V = np.zeros((n, 2))
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            d = X[j] - X[i]; r = np.hypot(d[0], d[1])
            if not r < c:
                continue
            e = d / r
            ni = np.array([-np.sin(T[i]), np.cos(T[i])])
            nj = np.array([-np.sin(T[j]), np.cos(T[j])])
            ci = M[i] * (ni @ e); cj = M[j] * (nj @ e)
            dci = -(M[i] * ni - ci * e) / r
            dcj = -(M[j] * nj - cj * e) / r
            U = np.exp(-r) - np.exp(-r / b)
            dU = -np.exp(-r) + np.exp(-r / b) / b
            grad = -(ci * cj + 1.0) * dU * e + U * (dci * cj + ci * dcj)
            V[i] -= tv * grad
    return V
def _central(X, T, M, b, c, tv):
    return _vel(X, T, np.zeros(len(X)), b, c, tv)
def _pair(a):
    a = np.asarray(a, dtype=float)
    if a.shape != (2,):
        return -1.0
    return float(a[0] + 3.0 * a[1])
assert np.allclose(_pair(solve_stacked_triad(0.22, 3.6, 2.2, 1.0, _vel)), target)

