import numpy as np
def _edge(limit):
    def fn(m):
        if m < limit:
            return np.array([2.0 + m, 1.9 - m])
        raise ValueError('no stacked equilibrium')
    return fn
def _stretch(rest, reach, gain):
    def fn(m):
        base = rest * (1.0 + gain * m * m)
        if base < reach:
            return np.array([base, 0.9 * rest])
        raise ValueError('base pair out of range')
    return fn
